True from collections import deque

def transform(grid):
    rows, cols = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            component = []
            queue = deque([(r, c)])
            seen.add((r, c))
            while queue:
                cr, cc = queue.popleft()
                component.append((cr, cc))
                for nr, nc in ((cr-1, cc), (cr+1, cc), (cr, cc-1), (cr, cc+1)):
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 0 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        queue.append((nr, nc))
            if len(component) > 1:
                for cr, cc in component:
                    out[cr][cc] = 8
    return out
